ALTER TABLE tlc.accounts ADD COLUMN IF NOT EXISTS business_segment text CHECK (business_segment IN ('commercial','residential'));
GRANT SELECT ON tlc.properties,tlc.projects,tlc.property_enquiries TO tlc_web_runtime;
CREATE POLICY batch05_property_read ON tlc.properties FOR SELECT TO tlc_web_runtime USING (EXISTS (SELECT 1 FROM tlc.accounts a JOIN tlc.account_roles r ON r.account_id=a.id WHERE a.auth_subject=nullif(current_setting('tlc.auth_subject',true),'') AND a.approval_state='active' AND a.account_kind='employee' AND (r.role='admin' OR (r.role='commercial_manager' AND properties.business_segment='commercial') OR (r.role='residential_manager' AND properties.business_segment='residential') OR (r.role IN ('inventory_manager','sales_executive','read_only') AND a.business_segment=properties.business_segment))));
CREATE POLICY batch05_project_read ON tlc.projects FOR SELECT TO tlc_web_runtime USING (EXISTS (SELECT 1 FROM tlc.accounts a JOIN tlc.account_roles r ON r.account_id=a.id WHERE a.auth_subject=nullif(current_setting('tlc.auth_subject',true),'') AND a.approval_state='active' AND a.account_kind='employee' AND (r.role='admin' OR (r.role='commercial_manager' AND projects.business_segment='commercial') OR (r.role='residential_manager' AND projects.business_segment='residential') OR (r.role IN ('inventory_manager','sales_executive','read_only') AND a.business_segment=projects.business_segment))));
CREATE POLICY batch05_enquiry_read ON tlc.property_enquiries FOR SELECT TO tlc_web_runtime USING (EXISTS (SELECT 1 FROM tlc.accounts a JOIN tlc.account_roles r ON r.account_id=a.id WHERE a.auth_subject=nullif(current_setting('tlc.auth_subject',true),'') AND a.approval_state='active' AND a.account_kind='employee' AND (r.role='admin' OR (r.role='sales_executive' AND property_enquiries.assigned_to=a.id) OR (r.role IN ('commercial_manager','residential_manager') AND (EXISTS (SELECT 1 FROM tlc.properties p WHERE p.id=property_enquiries.property_id) OR (property_enquiries.property_id IS NULL AND EXISTS (SELECT 1 FROM tlc.projects p WHERE p.id=property_enquiries.project_id)))))));
